// Dev-only script: imports some public workout templates of wger into src/data/wgerWorkouts.js.
// The app reads that generated file, so no token or network call is needed at runtime.
// The token is read from the WGER_TOKEN environment variable, it is never saved in the repo.
//
//   PowerShell:  $env:WGER_TOKEN = "your-token"; node scripts/import-wger.mjs
import { writeFileSync } from "node:fs";

const BASE_URL = "https://wger.de/api/v2";
const OUTPUT = new URL("../src/data/wgerWorkouts.js", import.meta.url);
const token = process.env.WGER_TOKEN;

// Templates chosen by hand: id on wger and the name shown in the app.
// Many others are incomplete: e.g. the StrongLifts ones have no squat and one row for each set.
const TEMPLATES = [
  { id: 52744, name: "Push Pull Legs" },
  { id: 65167, name: "Bro Split" },
  { id: 71372, name: "Upper/Lower" },
  { id: 51701, name: "Full Body" },
];

// wger language ids: Italian first, English as fallback
const LANGUAGES = [13, 2];

const DEFAULT_SETS = 3;
const DEFAULT_REST = 90;

if (!token) {
  console.error("Missing WGER_TOKEN: set it first, see the comment at the top.");
  process.exit(1);
}

async function get(path) {
  const response = await fetch(`${BASE_URL}/${path}`, {
    headers: { Accept: "application/json", Authorization: `Token ${token}` },
  });
  if (!response.ok) throw new Error(`wger answered ${response.status} on ${path}`);
  // Small pause, to be gentle with the public server
  await new Promise((resolve) => setTimeout(resolve, 120));
  return response.json();
}

// First value of a wger config list, e.g. sets_configs, as a number
function firstNumber(configs) {
  const value = Number.parseFloat(configs?.[0]?.value);
  return Number.isNaN(value) ? null : value;
}

const exerciseNames = new Map();

async function exerciseName(id) {
  if (!exerciseNames.has(id)) {
    const info = await get(`exerciseinfo/${id}/`);
    const translations = info.translations ?? [];
    const found =
      LANGUAGES.map((language) =>
        translations.find((translation) => translation.language === language),
      ).find(Boolean) ?? translations[0];
    exerciseNames.set(id, found?.name?.trim() || `Esercizio ${id}`);
  }
  return exerciseNames.get(id);
}

// "Repetitions" -> 8 or "8-12", seconds -> "30s", until failure -> "max"
function formatReps(entry, units) {
  const unit = units.get(entry.repetition_unit) ?? "Repetitions";
  const min = firstNumber(entry.repetitions_configs);
  const max = firstNumber(entry.max_repetitions_configs);

  if (/failure/i.test(unit)) return "max";
  const suffix = /second/i.test(unit) ? "s" : /minute/i.test(unit) ? "min" : "";
  if (min === null) return "max";
  if (max !== null && max !== min) return `${min}-${max}${suffix}`;
  return suffix ? `${min}${suffix}` : min;
}

async function convertEntry(entry, units) {
  const rir = firstNumber(entry.rir_configs);
  const exercise = {
    exerciseName: await exerciseName(entry.exercise),
    sets: firstNumber(entry.set_nr_configs) ?? DEFAULT_SETS,
    reps: formatReps(entry, units),
    // RPE is 10 minus the reps left in reserve, missing when wger has no value
    RPE: rir === null ? null : Math.max(10 - rir, 1),
    rest: firstNumber(entry.rest_configs) ?? DEFAULT_REST,
  };
  if (entry.type && entry.type !== "normal") exercise.technique = entry.type;
  return exercise;
}

const unitList = await get("setting-repetitionunit/");
const units = new Map(unitList.results.map((unit) => [unit.id, unit.name]));

const workouts = [];

for (const template of TEMPLATES) {
  console.log(`Importing ${template.name}...`);
  const structure = await get(`routine/${template.id}/structure/`);

  const days = [];
  for (const day of structure.days ?? []) {
    const entries = (day.slots ?? []).flatMap((slot) => slot.entries ?? []);
    // Rest days and empty days are not shown
    if (day.is_rest || entries.length === 0) continue;

    // The app already shows "DAY 1" above the name, so "Day 1 - Chest" becomes "Chest"
    const name = day.name.trim().replace(/^day\s*\d+\s*[-–:]\s*/i, "");

    const exercises = [];
    for (const entry of entries) exercises.push(await convertEntry(entry, units));
    days.push({ day: days.length + 1, name, exercises });
  }

  workouts.push({ id: `wger-${template.id}`, name: template.name, source: "wger", days });
}

const file = `// Generated by scripts/import-wger.mjs from the public templates of wger (https://wger.de).
// Do not edit by hand: change the script and run it again.
export const wgerWorkouts = ${JSON.stringify(workouts, null, 2)};
`;

writeFileSync(OUTPUT, file);
console.log(`Saved ${workouts.length} workouts in ${OUTPUT.pathname}`);
